@kbench.task(name="proofsec-task-001")
def proofsec_task_001(llm):
    cases = [
        {
            "id": "case_1_vulnerable",
            "scenario": "User A (id=10) requests /api/users/11/profile. The server returns User B's profile data without verifying authorization.",
            "expected": "Vulnerable"
        },
        {
            "id": "case_2_not_vulnerable",
            "scenario": "User A (id=10) requests /api/users/10/profile. The server validates the session token matches user ID 10 before returning data.",
            "expected": "Not Vulnerable"
        },
        {
            "id": "case_3_insufficient",
            "scenario": "User A requests /api/documents/12345. The server returns the document. There is no authentication check on this endpoint.",
            "expected": "Insufficient Evidence"
        },
        {
            "id": "case_4_vulnerable",
            "scenario": "User with 'guest' role sends POST /api/admin/delete_user. The server deletes the user because it only checks for authentication, not authorization roles.",
            "expected": "Vulnerable"
        },
        {
            "id": "case_5_insufficient",
            "scenario": "User A intercepts a request to /api/messages. The request contains a parameter 'msg_id=99'.",
            "expected": "Insufficient Evidence"
        }
    ]

    results = {}

    for case in cases:
        prompt = f"""You are an expert security code reviewer. Analyze the following scenario and determine if it represents a confirmed security vulnerability, no vulnerability, or if there is insufficient evidence to decide.

Scenario: {case['scenario']}

Output your decision strictly as one of the following labels: "Vulnerable", "Not Vulnerable", or "Insufficient Evidence". Do not explain your reasoning.
"""
        response = llm.prompt(prompt)
        kbench.assertions.assert_in(case['expected'], response, expectation=f"Expected '{case['expected']}' for {case['id']}")
        results[case['id']] = response

    return results
